    NotScaledReason.add_member(:code, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlString, location_name: 'Code', traits: {"smithy.api#documentation" => "<p>A code that represents the reason for not scaling.</p>\n         <p>Valid values:</p>\n         <ul>\n            <li>\n               <p>AutoScalingAnticipatedFlapping</p>\n            </li>\n            <li>\n               <p>TargetServicePutResourceAsUnscalable</p>\n            </li>\n            <li>\n               <p>AlreadyAtMaxCapacity</p>\n            </li>\n            <li>\n               <p>AlreadyAtMinCapacity</p>\n            </li>\n            <li>\n               <p>AlreadyAtDesiredCapacity</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
