    PredictiveScalingPolicyConfiguration.add_member(:metric_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: PredictiveScalingMetricSpecifications, location_name: 'MetricSpecifications', traits: {"smithy.api#documentation" => "<p>\n         This structure includes the metrics and target utilization to use for predictive scaling.\n      </p>\n         <p>This is an array, but we currently only support a single metric specification. That\n         is, you can specify a target value and a single metric pair, or a target value and one\n         scaling metric and one load metric.</p>", "smithy.api#required" => {}}))
    PredictiveScalingPolicyConfiguration.add_member(:mode, Smithy::Schema::Shapes::ShapeRef.new(shape: PredictiveScalingMode, location_name: 'Mode', traits: {"smithy.api#documentation" => "<p>\n         The predictive scaling mode. Defaults to <code>ForecastOnly</code> if not specified.\n      </p>"}))
    PredictiveScalingPolicyConfiguration.add_member(:scheduling_buffer_time, Smithy::Schema::Shapes::ShapeRef.new(shape: PredictiveScalingSchedulingBufferTime, location_name: 'SchedulingBufferTime', traits: {"smithy.api#documentation" => "<p>\n         The amount of time, in seconds, that the start time can be advanced.\n      </p>\n         <p>The value must be less than the forecast interval duration of 3600 seconds (60\n         minutes). Defaults to 300 seconds if not specified. </p>"}))
    PredictiveScalingPolicyConfiguration.add_member(:max_capacity_breach_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: PredictiveScalingMaxCapacityBreachBehavior, location_name: 'MaxCapacityBreachBehavior', traits: {"smithy.api#documentation" => "<p>\n         Defines the behavior that should be applied if the forecast capacity approaches or\n         exceeds the maximum capacity. Defaults to\n         <code>HonorMaxCapacity</code> if not specified.\n      </p>"}))
    PredictiveScalingPolicyConfiguration.add_member(:max_capacity_buffer, Smithy::Schema::Shapes::ShapeRef.new(shape: PredictiveScalingMaxCapacityBuffer, location_name: 'MaxCapacityBuffer', traits: {"smithy.api#documentation" => "<p>\n         The size of the capacity buffer to use when the forecast capacity is close to or\n         exceeds the maximum capacity. The value is specified as a percentage relative to the\n         forecast capacity. For example, if the buffer is 10, this means a 10 percent buffer,\n         such that if the forecast capacity is 50, and the maximum capacity is 40, then the\n         effective maximum capacity is 55.\n      </p>\n         <p>Required if the <code>MaxCapacityBreachBehavior</code> property is set to\n         <code>IncreaseMaxCapacity</code>, and cannot be used otherwise.</p>"}))
    PredictiveScalingPolicyConfiguration.type = Types::PredictiveScalingPolicyConfiguration
